us</th><th>Paid at</th><th>Reference</th></tr></thead><tbody>@foreach($round->contributions as $contribution)@php($memberLedger = $roundLedger['members'][$contribution->cycleMember->groupMember->id] ?? null)<tr><td><strong>{{ $contribution->cycleMember->groupMember?->displayName() ?: $contribution->cycleMember->groupMember->user->name }}</strong><small>{{ $contribution->cycleMember->groupMember?->displayPhone() ?: 'No phone' }}</small></td><td><strong>TZS {{ number_format($memberLedger['paid_amount'] ?? $contribution->amount) }}</strong><small>{{ $memberLedger ? 'Actual successful payment' : 'No ledger payment' }}</small></td><td><x-status :value="$isFutureRound && in_array($contribution->status->value, ['paid', 'paid_late'], true) ? ($isDailyContributions ? 'paid' : 'received_early') : $contribution->status"/></td><td>{{ $contribution->paid_at?->timezone('Africa/Dar_es_Salaam')->format('d M Y, H:i') ?? '-' }}</td><td class="mono">{{ $contribution->payment_reference ?: '-' }}</td></tr>@endforeach</tbody></table></div>@foreach($round->decisions as $decision)<div class="decision-note"><i data-lucide="file-check-2"></i><div><strong>{{ ucfirst(str_replace('_',' ',$decision->type->value)) }}</strong><p>{{ $decision->reason }}</p><small>{{ $decision->decider->name }} &middot; {{ $decision->decided_at->format('d M Y, H:i') }}</small></div></div>@endforeach</section>
